// src/legMeshes.js
// ============================================================================
// Реальная 3D-модель кухонной опоры — из присланных пользователем CAD-файлов
// (опора.obj / опора с клипсой.obj), а не параметрическое приближение.
// Меши запечены в base64 (позиции + нормали, треугольники, без индексации)
// прямо в код — отдельного файла на диске приложение не грузит (нет
// сервера, весь конструктор — статичные .js через <script>).
//
// Система координат исходников (метры, ось Y — вверх):
//   высота 0..0.1 (100 мм, низ опоры — верх площадки), диаметр видимой
//   части ≈ 0.054 (54 мм). У варианта «clip» клипса торчит в сторону +X.
// ============================================================================
(function () {
  'use strict';
  const NATIVE_HEIGHT = 0.1;   // м — высота исходной модели (низ опоры → верх площадки)
  const NATIVE_DIAMETER = 0.054; // м — видимый диаметр опоры (по флейтам/фланцу)

  const MESHES = {
    // «опора.obj» — без задействованной клипсы (клипса-заглушка не видна).
    plain: {
      pos: '',
      norm: '',
    },
    // «опора с клипсой.obj» — с полноразмерной клипсой сбоку (держит цоколь).
    clip: {
      pos: '',
      norm: '',
    },
  };

  function base64ToFloat32(b64) {
    let bytes;
    if (typeof atob === 'function') {
      const bin = atob(b64);
      bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    } else {
      // Node (headless-тесты) — atob нет в старых версиях, читаем через Buffer.
      bytes = new Uint8Array(Buffer.from(b64, 'base64'));
    }
    return new Float32Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 4);
  }

  const cache = {};
  // Строит (и кеширует) THREE.BufferGeometry для опоры — 'plain' | 'clip'.
  // Геометрия в исходных единицах (высота ≈ NATIVE_HEIGHT, м) — масштаб под
  // нужную высоту/диаметр опоры задаёт вызывающий код (см. viewer.js).
  function getGeometry(kind, THREE) {
    const key = kind === 'clip' ? 'clip' : 'plain';
    if (cache[key]) return cache[key];
    const src = MESHES[key];
    const positions = base64ToFloat32(src.pos);
    const normals = base64ToFloat32(src.norm);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
    cache[key] = geo;
    return geo;
  }

  window.Modul3D = window.Modul3D || {};
  window.Modul3D.legMeshes = { getGeometry, NATIVE_HEIGHT, NATIVE_DIAMETER };
})();
